-- ============================================================
-- 05-import-quizquestions.sql
-- FR-18: Import existing frontend quiz banks into MySQL
--
-- PRESERVATION RULE:
-- This script ONLY adds missing question rows.
-- Existing quizquestion rows are never deleted or updated.
-- Existing frontend JSON quiz banks are untouched.
-- Safety Practices (quiz_id 6) is intentionally NOT imported
-- because no module-6.json currently exists in the repository.
-- ============================================================

USE `awareness_platform`;

START TRANSACTION;










UPDATE `quiz` SET `number_of_questions` = (SELECT COUNT(*) FROM `quizquestion` WHERE `quiz_id` = 1) WHERE `quiz_id` = 1;
UPDATE `quiz` SET `number_of_questions` = (SELECT COUNT(*) FROM `quizquestion` WHERE `quiz_id` = 2) WHERE `quiz_id` = 2;
UPDATE `quiz` SET `number_of_questions` = (SELECT COUNT(*) FROM `quizquestion` WHERE `quiz_id` = 3) WHERE `quiz_id` = 3;
UPDATE `quiz` SET `number_of_questions` = (SELECT COUNT(*) FROM `quizquestion` WHERE `quiz_id` = 4) WHERE `quiz_id` = 4;
UPDATE `quiz` SET `number_of_questions` = (SELECT COUNT(*) FROM `quizquestion` WHERE `quiz_id` = 5) WHERE `quiz_id` = 5;
UPDATE `quiz` SET `number_of_questions` = (SELECT COUNT(*) FROM `quizquestion` WHERE `quiz_id` = 7) WHERE `quiz_id` = 7;
UPDATE `quiz` SET `number_of_questions` = (SELECT COUNT(*) FROM `quizquestion` WHERE `quiz_id` = 8) WHERE `quiz_id` = 8;
UPDATE `quiz` SET `number_of_questions` = (SELECT COUNT(*) FROM `quizquestion` WHERE `quiz_id` = 9) WHERE `quiz_id` = 9;
UPDATE `quiz` SET `number_of_questions` = (SELECT COUNT(*) FROM `quizquestion` WHERE `quiz_id` = 10) WHERE `quiz_id` = 10;

COMMIT;
