INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 1, 'The presence of "HTTPS" and a padlock icon in the browser address bar guarantees that a login website is legitimate and safe.', 'easy', 'standard', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 1, '"b"', 'False. Threat actors can easily acquire free SSL/TLS certificates for fraudulent domain names, displaying HTTPS padlock icons on malicious credential-harvesting websites.', 1, -1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 1 AND `order_index` = 0);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 1, 'Which domain name represents an example of "typosquatting"?', 'easy', 'standard', 'single', '[{"value":"a","text":"support.google.com"},{"value":"b","text":"login.microsoft.com"},{"value":"c","text":"security-update@micros0ft-verify.com"},{"value":"d","text":"portal.slack.com"}]', 2, '"c"', 'micros0ft-verify.com uses a zero (''0'') in place of the letter ''o'' to trick users into believing it is an official Microsoft communication channel.', 1, -1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 1 AND `order_index` = 1);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 1, 'What is the primary objective of an email phishing attack targeting remote employees?', 'easy', 'standard', 'single', '[{"value":"a","text":"To test home internet connection speeds"},{"value":"b","text":"To trick users into revealing credentials, sensitive data, or executing unauthorized actions"},{"value":"c","text":"To automatically upgrade operating system software"},{"value":"d","text":"To clean junk files from a local hard drive"}]', 1, '"b"', 'Email phishing uses deceptive messages to trick victims into sharing private credentials, executing malware, or surrendering sensitive organizational data.', 1, -1, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 1 AND `order_index` = 2);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 1, 'Why do quishing attacks often succeed when targeting remote employees?', 'medium', 'standard', 'single', '[{"value":"a","text":"Smartphones cannot connect to Wi-Fi networks"},{"value":"b","text":"Scanning the QR code shifts the browsing session to a mobile device outside the company''s desktop security monitoring"},{"value":"c","text":"QR codes automatically disable smartphone antivirus apps"},{"value":"d","text":"Mobile screens automatically encrypt all user passwords"}]', 1, '"b"', 'Scanning QR codes on personal phones redirects traffic outside the desktop perimeter firewalls and email monitoring systems maintained by corporate networks.', 1, -1, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 1 AND `order_index` = 3);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 1, 'You receive an email notification stating your company cloud portal requires urgent re-authentication, with a link included. What is the safest way to access the portal?', 'medium', 'scenario-based', 'single', '[{"value":"a","text":"Click the link in the email, enter credentials, then log out"},{"value":"b","text":"Open a fresh browser tab, type the verified official URL manually or use a saved bookmark"},{"value":"c","text":"Reply to the email asking if the link is safe"},{"value":"d","text":"Copy and paste the link into a personal social media post to ask colleagues"}]', 1, '"b"', 'Navigating independently via a trusted bookmark or manual URL entry completely bypasses any malicious redirects embedded in the email.', 1, -1, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 1 AND `order_index` = 4);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 1, 'Before clicking a hyperlinked "Verify Account" button in an email, you hover your mouse over it without clicking. Does this let you preview the actual destination URL before you click?', 'medium', 'scenario-based', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 0, '"a"', 'True. Hovering over a hyperlink reveals the true underlying web destination address in the browser or mail client status bar.', 1, -1, 5 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 1 AND `order_index` = 5);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 1, 'You scan a QR code from a vendor PDF. It opens a Google Sign-In page asking you to "Grant Full OAuth Permissions to App XYZ." Granting access is safe because the URL starts with accounts.google.com.', 'hard', 'scenario-based', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 1, '"b"', 'False. Malicious OAuth applications use real Google/Microsoft sign-in portals to request excessive account permissions. Once granted, the attacker gets persistent cloud access without needing your password.', 1, -1, 6 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 1 AND `order_index` = 6);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 1, 'A virtual assistant receives an email displaying the company CEO''s exact name and profile photo. The sender address is ceo-office@exec-mail-corp.com (not the corporate @company.com domain). The message requests an urgent purchase of gift card vouchers for an ongoing client event. What social engineering tactic is being deployed?', 'hard', 'scenario-based', 'single', '[{"value":"a","text":"Mass Ransomware Distribution"},{"value":"b","text":"Executive Spoofing via Combosquatting Phishing"},{"value":"c","text":"Authorized Corporate Expense Request"},{"value":"d","text":"Automated Database Synchronization"}]', 1, '"b"', 'The attacker uses executive identity impersonation combined with a combosquatted external domain (exec-mail-corp.com) to trick the assistant into making unauthorized purchases.', 1, -1, 7 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 1 AND `order_index` = 7);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 1, 'A remote software engineer receives an email containing a link to a "Critical Security Patch" hosted on github-downloads-security.net. What is the most rigorous way to confirm if this patch is legitimate?', 'hard', 'scenario-based', 'single', '[{"value":"a","text":"Click the link, download the file, and scan it with a free online tool"},{"value":"b","text":"Check official internal engineering channels (e.g., internal Slack/Teams or company repo) and consult the lead system administrator"},{"value":"c","text":"Forward the email to external contacts on LinkedIn to ask if they received it"},{"value":"d","text":"Reply directly asking the sender for their corporate employee ID number"}]', 1, '"b"', 'Internal verification via official out-of-band communication channels is the only reliable way to confirm patch validity.', 1, -1, 8 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 1 AND `order_index` = 8);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 1, 'If you realize you entered your corporate credentials into a fake login portal 5 minutes ago, what immediate steps must you execute? (Select ALL that apply)', 'hard', 'standard', 'multiple', '[{"value":"a","text":"Change the password immediately across your corporate account and any accounts reusing that password"},{"value":"b","text":"Revoke active user sessions and alert your organization''s IT/Security team"},{"value":"c","text":"Delete your browser history and turn off your home router for 24 hours"},{"value":"d","text":"Check active multi-factor authentication (MFA) devices registered to your account for unauthorized additions"}]', 0, '["a","b","d"]', 'Resetting credentials, revoking active sessions, alerting IT, and auditing registered MFA devices stops ongoing unauthorized account access. Deleting local browser history does not stop the remote attacker.', 1, -1, 9 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 1 AND `order_index` = 9);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 2, 'How does spear phishing differ from generic mass phishing?', 'easy', 'standard', 'single', '[{"value":"a","text":"Spear phishing is automated using pop-up advertisements"},{"value":"b","text":"Spear phishing is highly targeted at a specific individual or team using researched details"},{"value":"c","text":"Spear phishing only targets mobile phones using text messages"},{"value":"d","text":"Spear phishing requires physical entry into an office building"}]', 1, '"b"', 'Spear phishing relies on prior reconnaissance to tailor realistic messages directly to specific targets.', 1, -1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 2 AND `order_index` = 0);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 2, 'Public professional profiles on LinkedIn can provide attackers with information used to craft spear phishing messages.', 'easy', 'standard', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 0, '"a"', 'True. Attackers mine job titles, reporting structures, vendor software, and current projects from LinkedIn profiles to build convincing pretexts.', 1, -1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 2 AND `order_index` = 1);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 2, 'A vendor you''ve never worked with emails you a password-protected .zip file labeled "Invoice_Overdue.zip" and asks you to enter the password from a separate message to open it. Why might an attacker package a malicious attachment this way?', 'easy', 'scenario-based', 'single', '[{"value":"a","text":"To save hard drive storage space on remote laptops"},{"value":"b","text":"To prevent email security gateways from scanning the encrypted contents for malware"},{"value":"c","text":"To make the file download faster over home Wi-Fi networks"},{"value":"d","text":"Because password protection automatically executes scripts"}]', 1, '"b"', 'Email gateway scanners cannot inspect encrypted archive contents without the password, allowing malicious payloads past boundary defenses.', 1, -1, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 2 AND `order_index` = 2);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 2, 'Which public sources are commonly harvested by adversaries during the OSINT phase of a spear phishing campaign? (Select ALL that apply)', 'medium', 'standard', 'multiple', '[{"value":"a","text":"LinkedIn corporate organizational charts"},{"value":"b","text":"Public GitHub code repositories detailing software libraries"},{"value":"c","text":"Personal social media posts detailing travel or conference attendance"},{"value":"d","text":"Encrypted database servers operating behind private firewalls"}]', 0, '["a","b","c"]', 'LinkedIn, GitHub, and social media posts provide open public data. Private encrypted database servers are not public OSINT sources.', 1, -1, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 2 AND `order_index` = 3);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 2, 'Spear phishers only target executives; entry-level remote contractors are never targeted because they lack system permissions.', 'medium', 'standard', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 1, '"b"', 'Entry-level contractors are frequently targeted as initial access points to pivot deeper into enterprise networks or harvest credentials.', 1, -1, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 2 AND `order_index` = 4);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 2, 'You''ve been posting detailed updates about your work travel, conference attendance, and current projects on your public social media accounts. Does reducing this kind of detailed operational information lower your exposure to OSINT reconnaissance used in spear phishing?', 'medium', 'scenario-based', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 0, '"a"', 'True. Practicing digital footprint hygiene limits the intelligence attackers can use to build spear phishing lures.', 1, -1, 5 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 2 AND `order_index` = 5);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 2, 'An email claiming to be from your company''s HR department contains a link to “Updated W-2 Tax Forms.” The link URL points to an external domain unrelated to your company. What is the safest course of action?', 'hard', 'scenario-based', 'single', '[{"value":"a","text":"Click the link and enter your Social Security Number."},{"value":"b","text":"Hover over the link, identify the external domain, do not click, and report it to security/HR."},{"value":"c","text":"Email your password to HR to check for you."},{"value":"d","text":"Ignore all future HR emails forever."}]', 1, '"b"', 'Identifying external, non-company domain names by hovering over links helps detect phishing portals before entering credentials.', 1, -1, 6 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 2 AND `order_index` = 6);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 2, 'Spear phishing relies solely on technical software exploits and does not use psychological manipulation.', 'hard', 'standard', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 1, '"b"', 'Spear phishing is a socio-technical attack combining technical delivery vectors with psychological manipulation (trust, urgency, authority).', 1, -1, 7 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 2 AND `order_index` = 7);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 2, 'What step should you take before opening a password-protected .zip file from an external party?', 'hard', 'standard', 'single', '[{"value":"a","text":"Open it on a personal device to protect work systems."},{"value":"b","text":"Verify the source out-of-band and inspect unzipped contents in an isolated environment or sandbox."},{"value":"c","text":"Forward the password to your bank."},{"value":"d","text":"Disable your endpoint firewall."}]', 1, '"b"', 'Verifying the source through another channel and inspecting files securely prevents payload execution.', 1, -1, 8 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 2 AND `order_index` = 8);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 2, 'An attacker researching you before sending a spear-phishing email finds your public GitHub profile. What information could they gather there to make their message more believable?', 'hard', 'scenario-based', 'single', '[{"value":"a","text":"Your private home Wi-Fi password"},{"value":"b","text":"Programming languages used, active repositories, and collaborator usernames"},{"value":"c","text":"Your hardware MFA seed keys"},{"value":"d","text":"Your credit card PIN"}]', 1, '"b"', 'Public GitHub repositories display technical environments, active projects, and peer collaborators.', 1, -1, 9 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 2 AND `order_index` = 9);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 3, 'You receive a text message from an unknown number containing a suspicious link and urging you to act immediately. What is the safest action to take?', 'easy', 'scenario-based', 'single', '[{"value":"a","text":"Tap the link to see where it leads."},{"value":"b","text":"Delete the message, report it, and do not click any links."},{"value":"c","text":"Forward the message to 10 friends."},{"value":"d","text":"Call the unknown number and insult the caller."}]', 1, '"b"', 'Refraining from interaction and deleting/reporting the message mitigates risk.', 1, -1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 3 AND `order_index` = 0);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 3, 'You get an unsolicited promotional text from an unknown sender and reply "STOP," expecting to be removed from their list. Will this safely unsubscribe you from a smishing scammer''s messages?', 'easy', 'scenario-based', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 1, '"b"', 'Replying to a scam text confirms to the attacker that your phone number is active, leading to more targeted attacks.', 1, -1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 3 AND `order_index` = 1);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 3, 'What does the term "Smishing" stand for?', 'easy', 'standard', 'single', '[{"value":"a","text":"Secure Mail Phishing"},{"value":"b","text":"SMS Phishing (Short Message Service Phishing)"},{"value":"c","text":"Software Management Phishing"},{"value":"d","text":"System Media Injection"}]', 1, '"b"', 'Smishing combines "SMS" (text messaging) and "phishing".', 1, -1, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 3 AND `order_index` = 2);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 3, 'You receive a text message: "USPS Alert: Your package cannot be delivered due to an incorrect house number. Update info here: bit.ly/3xY9zQ". You are expecting a package. What is the correct action?', 'medium', 'scenario-based', 'single', '[{"value":"a","text":"Tap the link immediately and enter your home address."},{"value":"b","text":"Do not tap the link; open your official USPS app or browser bookmark independently to track the package."},{"value":"c","text":"Reply \\"STOP\\" to check if the sender is real."},{"value":"d","text":"Text back your credit card details."}]', 1, '"b"', 'Always verify parcel delivery alerts by accessing the official website or app independently, never through unsolicited SMS links.', 1, -1, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 3 AND `order_index` = 3);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 3, 'Legitimate banks routinely send text messages asking customers to directly text back their full PIN or password.', 'medium', 'standard', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 1, '"b"', 'Financial institutions explicitly prohibit requesting sensitive passwords, PINs, or OTPs via text.', 1, -1, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 3 AND `order_index` = 4);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 3, 'What shortcode number can users in many regions forward spam or smishing texts to for reporting?', 'medium', 'standard', 'single', '[{"value":"a","text":"911"},{"value":"b","text":"7726 (SPAM)"},{"value":"c","text":"411"},{"value":"d","text":"0000"}]', 1, '"b"', 'Forwarding spam texts to 7726 (SPAM) alerts carriers to investigate and block malicious sender numbers.', 1, -1, 5 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 3 AND `order_index` = 5);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 3, 'You receive a WhatsApp text from an unknown international number displaying your company logo: "Hi, I am John from Corporate IT. We are updating mobile profiles. Click this link to install our security certificate." How should you respond?', 'hard', 'scenario-based', 'single', '[{"value":"a","text":"Install the certificate immediately."},{"value":"b","text":"Ignore and report the WhatsApp message; IT does not deploy security certificates via unsolicited WhatsApp texts."},{"value":"c","text":"Send the sender your personal national ID card."},{"value":"d","text":"Ask the sender to call your personal home phone."}]', 1, '"b"', 'Corporate IT security profiles are deployed through formal Mobile Device Management (MDM) tools, never random instant messages.', 1, -1, 6 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 3 AND `order_index` = 6);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 3, 'Advanced smishing kits can deploy mobile malware that automatically reads incoming SMS verification codes and forwards them to a remote C2 server.', 'hard', 'standard', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 0, '"a"', 'Malicious mobile applications (e.g., infected APKs) can request SMS permissions to intercept and exfiltrate OTPs.', 1, -1, 7 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 3 AND `order_index` = 7);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 3, 'You attempt to log into your work portal. A minute later, you receive a text: "IT Helpdesk: We detected an abnormal login. Reply YES with the code you just received to block the login." What is happening?', 'hard', 'scenario-based', 'single', '[{"value":"a","text":"IT is securely helping you protect your account."},{"value":"b","text":"An attacker triggered your real login prompt and is trying to trick you into texting them your OTP."},{"value":"c","text":"Your phone has a hardware virus that generates text messages."},{"value":"d","text":"Your mobile service provider is upgrading its network towers."}]', 1, '"b"', 'Attackers trigger a real login prompt to generate a genuine OTP, then smish the victim to forward that OTP to complete the breach.', 1, -1, 8 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 3 AND `order_index` = 8);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 3, 'What technology allows scammers to change the phone number or name displayed on your mobile incoming text screen?', 'hard', 'standard', 'single', '[{"value":"a","text":"OAuth 2.0"},{"value":"b","text":"Caller ID / Alpha-Numeric Sender ID Spoofing"},{"value":"c","text":"Transport Layer Security"},{"value":"d","text":"Fiber Optic Splicing"}]', 1, '"b"', 'Sender ID spoofing allows SMS gateways to modify the header sender text displayed on receiver phones.', 1, -1, 9 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 3 AND `order_index` = 9);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 4, 'Caller ID information displayed on a smartphone screen can be easily spoofed by attackers using web VoIP services.', 'easy', 'standard', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 1, '"b"', 'Caller ID metadata can be modified by outbound VoIP gateways to show fake names and numbers.', 1, -1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 4 AND `order_index` = 0);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 4, 'An unknown caller on the phone becomes aggressive and demands that you immediately verify your account details over the call. What is the best immediate response?', 'easy', 'scenario-based', 'single', '[{"value":"a","text":"Comply with their demands to avoid trouble."},{"value":"b","text":"Terminate the call (hang up) and report the incident to security."},{"value":"c","text":"Apologize and offer your personal credentials."},{"value":"d","text":"Hold the line for 5 hours without speaking."}]', 1, '"b"', 'Aggressive emotional pressure is a hallmark of vishing; hanging up terminates the attack vector.', 1, -1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 4 AND `order_index` = 1);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 4, 'Official company helpdesks frequently call remote workers unannounced to demand their personal email passwords.', 'easy', 'standard', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 1, '"b"', 'Legitimate helpdesks do not require your private account passwords to perform administrative tasks.', 1, -1, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 4 AND `order_index` = 2);
