INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 8, 'Which of the following indicate that an invoice update request may be a BEC attempt? (Select TWO)', 'hard', 'standard', 'multiple', '[{"value":"a","text":"The invoice email comes from a domain with a slight typo (supplier-billing.co instead of supplier-billing.com)."},{"value":"b","text":"The request insists that payment MUST be wired within 2 hours to prevent account closure."},{"value":"c","text":"The vendor''s banking details match the historical records on file."},{"value":"d","text":"The request was submitted through your company''s secure vendor portal."}]', 0, '["a","b"]', 'Typosquatted domains and extreme artificial time pressure are indicators of BEC fraud.', 1, -1, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 8 AND `order_index` = 3);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 8, 'Calling the phone number listed on a suspicious new invoice is a safe way to verify if the invoice''s bank account changes are real.', 'easy', 'standard', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 1, '"b"', 'If the invoice is fake, the phone number on it leads directly to the scammer. Use trusted numbers from master contracts.', 1, -1, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 8 AND `order_index` = 4);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 8, 'What internal financial control requires two separate individuals to review and approve wire transfers above a designated threshold?', 'medium', 'standard', 'single', '[{"value":"a","text":"Single-user sign-off"},{"value":"b","text":"Dual-Custody / Dual-Control Authorization"},{"value":"c","text":"Automatic password expiration"},{"value":"d","text":"Anonymous payment processing"}]', 1, '"b"', 'Dual-custody ensures that a single manipulated employee cannot execute unauthorized transfers alone.', 1, -1, 5 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 8 AND `order_index` = 5);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 8, 'A long-time vendor emails an invoice for $22,000. The invoice matches the expected amount, but a note says: "Our bank is undergoing an audit. Wire payment to our new overseas account." What is the safest response?', 'hard', 'scenario-based', 'single', '[{"value":"a","text":"Wire the $22,000 to the overseas account to avoid late fees."},{"value":"b","text":"Hold the payment and contact the vendor''s CFO/accounting lead using your established, verified phone directory."},{"value":"c","text":"Pay the invoice in cash."},{"value":"d","text":"Forward the email to 5 random contacts."}]', 1, '"b"', 'Audit excuses for sudden overseas account changes are common BEC pretexts requiring verification.', 1, -1, 6 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 8 AND `order_index` = 6);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 8, 'In an email header, what field shows the actual mail server that sent the message, helping reveal domain spoofing?', 'hard', 'standard', 'single', '[{"value":"a","text":"Subject:"},{"value":"b","text":"Return-Path: / Originating IP Header"},{"value":"c","text":"Font-Family:"},{"value":"d","text":"Attachment-Size:"}]', 1, '"b"', 'Email headers reveal true server origins, exposing sender address spoofing.', 1, -1, 7 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 8 AND `order_index` = 7);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 8, 'Business Email Compromise (BEC) attacks only use fake domains; they never involve real, compromised vendor email accounts.', 'medium', 'standard', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 1, '"b"', 'Attackers frequently compromise real vendor accounts (Vendor Email Compromise) to send fraudulent invoices from actual mailboxes.', 1, -1, 8 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 8 AND `order_index` = 8);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 8, 'Why do BEC scammers target remote finance workers right before weekends or major holidays?', 'medium', 'scenario-based', 'single', '[{"value":"a","text":"Internet speeds are faster on weekends."},{"value":"b","text":"Staff are rushing to finish tasks and are more likely to bypass verification steps under time pressure."},{"value":"c","text":"Banks are closed on weekends so money transfers are free."},{"value":"d","text":"Computers automatically turn off on holidays."}]', 1, '"b"', 'Rushing before deadlines reduces vigilance, increasing the likelihood that security protocols will be skipped.', 1, -1, 9 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 8 AND `order_index` = 9);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 9, 'What is the primary goal of scammers running fake remote job outreach campaigns?', 'easy', 'standard', 'single', '[{"value":"a","text":"To help workers improve their resumes."},{"value":"b","text":"To steal Personally Identifiable Information (PII), commit identity theft, or execute equipment check fraud."},{"value":"c","text":"To provide free laptops to remote contractors."},{"value":"d","text":"To test local internet connection speeds."}]', 1, '"b"', 'Fake job scams harvest PII and run advance-fee equipment check schemes (Ravenelle et al., 2022).', 1, -1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 9 AND `order_index` = 0);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 9, 'A legitimate international company will routinely hire remote employees for high-paying roles based purely on a 10-minute text conversation on Telegram without any video or voice interviews.', 'easy', 'standard', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 1, '"b"', 'Text-only "interviews" on anonymous messaging apps are major indicators of recruitment fraud.', 1, -1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 9 AND `order_index` = 1);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 9, 'You are hired for a remote position. The company mails you a $3,000 check and instructs you to deposit it, keep $500 as a sign-on bonus, and wire $2,500 to an "approved software vendor." What should you do?', 'medium', 'scenario-based', 'single', '[{"value":"a","text":"Wire the $2,500 immediately."},{"value":"b","text":"Recognize this as a fake check scam; do not wire any money and report the fraudulent offer."},{"value":"c","text":"Keep the full $3,000 and buy personal items."},{"value":"d","text":"Mail $2,500 in cash to the vendor."}]', 1, '"b"', 'Fake check scams rely on victims wiring real money before the bank identifies the deposited check as fraudulent.', 1, -1, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 9 AND `order_index` = 2);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 9, 'Which of the following details indicate that a remote job offer may be fraudulent? (Select TWO)', 'hard', 'standard', 'multiple', '[{"value":"a","text":"The recruiter asks for your online banking login credentials to set up direct deposit."},{"value":"b","text":"The job offer comes from an email address using a lookalike domain (careers-google-jobs.com)."},{"value":"c","text":"The interview was conducted via a scheduled video conference with HR personnel."},{"value":"d","text":"The job contract clearly states working hours and payment terms."}]', 0, '["a","b"]', 'Requesting bank passwords and using lookalike email domains indicate recruitment fraud.', 1, -1, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 9 AND `order_index` = 3);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 9, 'Legitimate employers require new hires to pay application fees or background check fees upfront via cryptocurrency.', 'easy', 'standard', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 1, '"b"', 'Legitimate employers cover hiring and background check costs; demanding crypto payments indicates fraud.', 1, -1, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 9 AND `order_index` = 4);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 9, 'What type of sensitive data is targeted during pre-employment PII harvesting scams?', 'medium', 'standard', 'single', '[{"value":"a","text":"Public social media posts"},{"value":"b","text":"Passport scans, government ID numbers, home addresses, and bank account numbers"},{"value":"c","text":"Favorite movie genres"},{"value":"d","text":"Public software documentation"}]', 1, '"b"', 'PII is harvested to commit identity theft, open fraudulent credit lines, or breach accounts.', 1, -1, 5 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 9 AND `order_index` = 5);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 9, 'You receive an email from hr@microsoft-remote-careers.site inviting you to apply for an administrative position. How can you verify if this domain belongs to Microsoft?', 'hard', 'scenario-based', 'single', '[{"value":"a","text":"Trust it because it has \\"Microsoft\\" in the name."},{"value":"b","text":"Check Microsoft''s official corporate website (microsoft.com/careers) or contact their verified talent team directly."},{"value":"c","text":"Reply to the email asking if they are real."},{"value":"d","text":"Click all links in the email footer."}]', 1, '"b"', 'Always cross-reference job outreach domains against official corporate career portals.', 1, -1, 6 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 9 AND `order_index` = 6);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 9, 'How does the fake equipment check scam operate?', 'hard', 'standard', 'single', '[{"value":"a","text":"The employer sends real laptops that do not work."},{"value":"b","text":"The employer sends a counterfeit check, instructs the worker to wire money to a fake vendor, and the check bounces later."},{"value":"c","text":"The employer steals the worker''s home furniture."},{"value":"d","text":"The employer installs free antivirus software on the worker''s phone."}]', 1, '"b"', 'The counterfeit check bounces after the victim has already transferred real personal funds to the scammer.', 1, -1, 7 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 9 AND `order_index` = 7);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 9, 'Scammers frequently copy authentic logos, employee photos, and executive names from LinkedIn to create convincing fake recruiter profiles.', 'medium', 'standard', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 0, '"a"', 'Copied branding assets build false credibility and lower applicant vigilance.', 1, -1, 8 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 9 AND `order_index` = 8);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 9, 'What is the primary risk of uploading your full unredacted driver''s license or passport scan to an unverified job portal?', 'medium', 'scenario-based', 'single', '[{"value":"a","text":"It consumes cloud storage space."},{"value":"b","text":"It enables threat actors to execute identity theft, register fraudulent accounts, or conduct loan fraud in your name."},{"value":"c","text":"It changes your computer screen brightness."},{"value":"d","text":"It automatically cancels your driver''s license."}]', 1, '"b"', 'Unredacted government IDs are primary assets used in identity fraud and unauthorized account creation.', 1, -1, 9 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 9 AND `order_index` = 9);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 10, 'Why do cybercriminals frequently target Virtual Assistants (VAs) in executive impersonation attacks?', 'easy', 'standard', 'single', '[{"value":"a","text":"VAs are responsible for writing all company software code."},{"value":"b","text":"VAs possess administrative access, schedule control, and are socialized to respond rapidly to executive commands."},{"value":"c","text":"VAs do not use internet connections."},{"value":"d","text":"VAs are legally responsible for company tax payments."}]', 1, '"b"', 'VAs hold central administrative access and high-level trust, making them high-value targets (Lazarus, 2024).', 1, -1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 10 AND `order_index` = 0);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 10, 'An email from a CEO requesting that a Virtual Assistant purchase $1,000 in Apple gift cards for a "client emergency" is almost certainly a social engineering scam.', 'easy', 'standard', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 0, '"a"', 'Requesting gift card purchases is a primary financial scam tactic; legitimate businesses do not use gift cards for emergency corporate transactions.', 1, -1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 10 AND `order_index` = 1);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 10, 'You receive a message on Telegram from your remote boss: "I am on a plane with no voice signal. Send me the MFA code that was just sent to your phone so I can access my email." What should you do?', 'medium', 'scenario-based', 'single', '[{"value":"a","text":"Send the MFA code immediately via Telegram."},{"value":"b","text":"Do not send the MFA code. MFA passcodes must never be shared, and the request is a credential interception attempt."},{"value":"c","text":"Post the MFA code on LinkedIn."},{"value":"d","text":"Email the code to the entire company."}]', 1, '"b"', 'MFA tokens grant account access and must never be shared, even if the requester claims to be an executive.', 1, -1, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 10 AND `order_index` = 2);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 10, 'Which of the following elements are red flags indicative of executive impersonation? (Select TWO)', 'hard', 'standard', 'multiple', '[{"value":"a","text":"The sender instructs you NOT to call them to verify the request because they are \\"in an urgent meeting.\\""},{"value":"b","text":"The request arrives via an official internal ticketing system with manager approval."},{"value":"c","text":"The message comes from a personal webmail address like ceo.companyname@gmail.com."},{"value":"d","text":"The request asks you to follow standard, documented procurement policies."}]', 0, '["a","c"]', 'Prohibiting voice verification and using external webmail accounts are classic executive spoofing indicators.', 1, -1, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 10 AND `order_index` = 3);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 10, 'Threat actors use psychological authority pressure to make Virtual Assistants feel that questioning an executive''s request will lead to immediate firing.', 'easy', 'standard', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 0, '"a"', 'Fear of disciplinary action is manipulated to force VAs to bypass security checks.', 1, -1, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 10 AND `order_index` = 4);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 10, 'What is "Out-of-Band (OOB) Verification" in the context of Virtual Assistant workflows?', 'medium', 'standard', 'single', '[{"value":"a","text":"Verifying a request using a different, independent communication method than the one used to send the request."},{"value":"b","text":"Replying to an email using ALL CAPS."},{"value":"c","text":"Sending a text message to the same scammer."},{"value":"d","text":"Deleting your email inbox."}]', 0, '"a"', 'OOB verification confirms identity via a separate, trusted channel (e.g., calling a known phone number).', 1, -1, 5 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 10 AND `order_index` = 5);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 10, 'You manage the calendar for a remote Vice President. An external consultant emails asking you to add a Zoom link to the VP''s calendar for a "confidential acquisition meeting." The email attachment is Meeting_Agenda.docm. What should you do?', 'hard', 'scenario-based', 'single', '[{"value":"a","text":"Open the attachment and click \\"Enable Macros\\" to see the agenda."},{"value":"b","text":"Do not open the attachment; verify the meeting request directly with the VP or your internal team lead before updating the calendar."},{"value":"c","text":"Share the VP''s personal home address with the consultant."},{"value":"d","text":"Forward the file to your personal family members."}]', 1, '"b"', 'Unsolicited macro-enabled files (.docm) are common malware delivery vectors.', 1, -1, 6 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 10 AND `order_index` = 6);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 10, 'What term describes an attacker flooding a Virtual Assistant''s phone with dozens of login push notifications late at night in hopes the VA will tap "Approve"?', 'hard', 'standard', 'single', '[{"value":"a","text":"Credential stuffing"},{"value":"b","text":"Push Bombing / MFA Fatigue Attack"},{"value":"c","text":"Port Scanning"},{"value":"d","text":"SQL Injection"}]', 1, '"b"', 'MFA fatigue exploits distraction and frustration to coerce push approvals.', 1, -1, 7 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 10 AND `order_index` = 7);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 10, 'If an executive texts you from a new, unverified phone number claiming they lost their device, you should immediately grant them full access to all company cloud drives without secondary verification.', 'medium', 'standard', 'single', '[{"value":"a","text":"True"},{"value":"b","text":"False"}]', 1, '"b"', 'Identity must be independently verified through official channels before granting access from new devices.', 1, -1, 8 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 10 AND `order_index` = 8);
INSERT INTO `quizquestion` (`quiz_id`, `question_text`, `category`, `question_type`, `answer_type`, `options`, `correct_option_index`, `correct_answer`, `explanation`, `points_correct`, `points_incorrect`, `order_index`) SELECT 10, 'Why do pretexters impersonating executives create artificial time emergencies ("Need this done in 15 minutes before board meeting")?', 'medium', 'scenario-based', 'single', '[{"value":"a","text":"To help the Virtual Assistant finish work early."},{"value":"b","text":"To induce panic and reduce the VA''s time to perform critical verification checks."},{"value":"c","text":"To reduce internet server usage."},{"value":"d","text":"Because executives cannot wait more than 15 minutes for anything."}]', 1, '"b"', 'Artificial time pressure suppresses analytical thinking and security protocol adherence.', 1, -1, 9 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quizquestion` WHERE `quiz_id` = 10 AND `order_index` = 9);
